import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { authService } from '../authService';
import { supabase } from '../supabaseClient';
import {
  AppBar,
  Avatar,
  Box,
  Button,
  Card,
  CardContent,
  CardActionArea,
  Chip,
  Container,
  Grid,
  IconButton,
  Menu,
  MenuItem,
  Toolbar,
  Typography,
  useTheme,
  LinearProgress,
  Tooltip,
  Stack,
  Divider,
  ListItemIcon,
  Paper
} from '@mui/material';
import {
  WaterDrop,
  Apartment,
  BusinessCenter,
  MonetizationOn,
  HealthAndSafety,
  CardMembership,
  MenuBook,
  Settings,
  Logout,
  Person,
  Lock,
  ArrowForward,
  Info
} from '@mui/icons-material';
import { showNotification } from './Notification';
import EventGreetingModal from './common/EventGreetingModal';
import ManageEventsDialog from './common/ManageEventsDialog';
import { eventService } from '../services/eventService';

const SystemsPortal = ({ onLogout }) => {
  const [user, setUser] = useState(null);
  const [anchorEl, setAnchorEl] = useState(null);
  const [allowedSystems, setAllowedSystems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeEvent, setActiveEvent] = useState(null);
  const [showGreeting, setShowGreeting] = useState(false);
  const [showManageEvents, setShowManageEvents] = useState(false);
  const navigate = useNavigate();
  const theme = useTheme();

  useEffect(() => {
    document.title = 'Systems Portal - LGU Concepcion';
    const checkUserAndFetchSystems = async () => {
      let currentUser = authService.getUserSession();
      
      if (!currentUser) {
        navigate('/login');
        return;
      }

      // Verify user department from DB to ensure fresh data
      try {
        const { data: userProfile, error: userError } = await supabase
          .from('users')
          .select('*')
          .eq('userid', currentUser.userid)
          .single();

        if (userProfile && !userError) {
          // Update local session if department changed
          if (userProfile.department !== currentUser.department) {
            console.log('Updating stale department:', currentUser.department, '->', userProfile.department);
            currentUser = { ...currentUser, department: userProfile.department, role: userProfile.role };
            authService.setUserSession(currentUser);
          }
        }
      } catch (err) {
        console.error('Error verifying user profile:', err);
      }

      setUser(currentUser);
      fetchAllowedSystems(currentUser);
    };

    // Fetch active event
    const loadEvent = async () => {
      const event = await eventService.getActiveEvent();
      if (event) {
        // Check if user suppressed this specific event
        const isHidden = sessionStorage.getItem(`hideEvent_${event.id}`);
        if (!isHidden) {
          setActiveEvent(event);
          setShowGreeting(true);
        }
      }
    };

    loadEvent();
    checkUserAndFetchSystems();
  }, [navigate]);

  const fetchAllowedSystems = async (currentUser) => {
    setLoading(true);
    try {
      if (currentUser?.role === 'superadmin') {
        setAllowedSystems(systems.map(s => s.id));
        setLoading(false);
        return;
      }

      if (!currentUser.department) {
        setAllowedSystems([]);
        setLoading(false);
        return;
      }

      const { data: deptData, error: deptError } = await supabase
        .from('lgu_departments')
        .select('id')
        .eq('department_name', currentUser.department)
        .eq('is_active', true)
        .single();

      if (deptError || !deptData) {
        console.error('Department not found:', deptError);
        setAllowedSystems([]);
        setLoading(false);
        return;
      }

      const { data: systemsData, error: systemsError } = await supabase
        .from('department_systems')
        .select('system_id')
        .eq('department_id', deptData.id);

      if (systemsError) {
        console.error('Error fetching systems:', systemsError);
        setAllowedSystems([]);
      } else {
        const systemIds = systemsData.map(s => s.system_id);
        console.log('Fetched allowed systems:', systemIds);
        
        // Explicitly remove business-permit for Accounting department if present
        if (currentUser.department?.toLowerCase().includes('accounting')) {
          console.log('Applying Accounting restriction for BPLO');
          setAllowedSystems(systemIds.filter(id => id !== 'business-permit'));
        } else {
          setAllowedSystems(systemIds);
        }
      }
    } catch (error) {
      console.error('Error:', error);
      setAllowedSystems([]);
    } finally {
      setLoading(false);
    }
  };

  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleLogout = () => {
    handleMenuClose();
    authService.logout();
    if (onLogout) {
      onLogout();
    }
    navigate('/login', { replace: true });
  };

  const systems = [
    {
      id: 'water-billing',
      name: 'Water Billing System',
      description: 'Manage water consumption billing and payments',
      icon: <WaterDrop fontSize="large" />,
      color: '#3b82f6',
      path: '/portal/water-billing/dashboard',
      available: true
    },
    {
      id: 'property-tax',
      name: 'Real Property Tax System',
      description: 'Real property tax assessment and collection',
      icon: <Apartment fontSize="large" />,
      color: '#10b981',
      path: '/portal/property-tax/dashboard',
      available: true
    },
    {
      id: 'business-permit',
      name: 'Business Permit & Licensing',
      description: 'Business registration and permit processing',
      icon: <BusinessCenter fontSize="large" />,
      color: '#f59e0b',
      path: '/portal/business-permit/dashboard',
      available: true
    },
    {
      id: 'treasury',
      name: 'Treasury Management',
      description: 'Revenue collection and financial management',
      icon: <MonetizationOn fontSize="large" />,
      color: '#8b5cf6',
      path: '/portal/treasury',
      available: false
    },
    {
      id: 'rural-health',
      name: 'Rural Health Unit',
      description: 'Health services, patient records, and medical management',
      icon: <HealthAndSafety fontSize="large" />,
      color: '#ef4444',
      path: '/portal/rural-health/dashboard',
      available: true
    },
    {
      id: 'civil-registry',
      name: 'Municipal Civil Registry',
      description: 'Birth, marriage, death certificates, and CENOMAR',
      icon: <CardMembership fontSize="large" />,
      color: '#667eea',
      path: '/portal/civil-registry/home',
      available: true
    },
    {
      id: 'e-logbook',
      name: 'e-LogBook',
      description: 'Track documents, vouchers, CAFOA, checks, and more',
      icon: <MenuBook fontSize="large" />,
      color: '#f97316',
      path: '/portal/e-logbook/home',
      available: true
    },
    {
      id: 'settings',
      name: 'System Settings',
      description: 'Manage users, departments, and system configuration',
      icon: <Settings fontSize="large" />,
      color: '#6b7280',
      path: '/portal/settings/users',
      available: true
    }
  ];

  const filteredSystems = systems.filter(system => system.available);

  const handleSystemClick = (system) => {
    // Final safety check for Accounting
    if (user?.department?.toLowerCase().includes('accounting') && system.id === 'business-permit') {
      showNotification('Access Denied: Restricted for Accounting Department', 'error');
      return;
    }

    const isAllowed = allowedSystems.includes(system.id);
    if (system.available && isAllowed) {
      sessionStorage.setItem('currentSystem', system.id);
      sessionStorage.setItem('currentSystemColor', system.color);
      navigate(system.path);
    }
  };

  if (!user || loading) {
    return (
      <Box sx={{ width: '100%', mt: 4 }}>
        <LinearProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ minHeight: '100vh', bgcolor: 'background.default' }}>
      <AppBar position="static" color="default" elevation={1} sx={{ bgcolor: 'white' }}>
        <Container maxWidth="xl">
          <Toolbar disableGutters>
            <Avatar sx={{ bgcolor: 'primary.main', mr: 2 }}>
              <Apartment />
            </Avatar>
            <Box sx={{ flexGrow: 1 }}>
              <Typography variant="h6" color="text.primary" fontWeight="bold">
                Municipal Treasurer's Office
              </Typography>
              <Typography variant="caption" color="text.secondary">
                Online Systems Portal
              </Typography>
            </Box>

            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <Box sx={{ textAlign: 'right', mr: 2, display: { xs: 'none', sm: 'block' } }}>
                <Typography variant="subtitle2" color="text.primary" fontWeight="bold">
                  {user.firstname} {user.lastname}
                </Typography>
                <Typography variant="caption" color="text.secondary">
                  {user.role}
                </Typography>
              </Box>
              <IconButton onClick={handleMenuOpen} sx={{ p: 0 }}>
                <Avatar sx={{ bgcolor: 'primary.main' }}>
                  {user.firstname.charAt(0)}{user.lastname.charAt(0)}
                </Avatar>
              </IconButton>
              <Menu
                anchorEl={anchorEl}
                open={Boolean(anchorEl)}
                onClose={handleMenuClose}
                transformOrigin={{ horizontal: 'right', vertical: 'top' }}
                anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
              >
                <MenuItem onClick={handleMenuClose}>
                  <ListItemIcon>
                    <Person fontSize="small" />
                  </ListItemIcon>
                  Profile
                </MenuItem>
                {user?.role === 'superadmin' && (
                  <MenuItem onClick={() => { handleMenuClose(); setShowManageEvents(true); }}>
                    <ListItemIcon>
                      <Settings fontSize="small" />
                    </ListItemIcon>
                    Manage Events
                  </MenuItem>
                )}
                <Divider />
                <MenuItem onClick={handleLogout}>
                  <ListItemIcon>
                    <Logout fontSize="small" />
                  </ListItemIcon>
                  Logout
                </MenuItem>
              </Menu>
            </Box>
          </Toolbar>
        </Container>
      </AppBar>

      <Container maxWidth="xl" sx={{ py: 6 }}>
        <Box sx={{ mb: 6 }}>
          <Typography variant="h4" fontWeight="bold" gutterBottom>
            Welcome back, {user.firstname}!
          </Typography>
          <Typography variant="subtitle1" color="text.secondary">
            Select a system to access
          </Typography>
        </Box>

        <Grid container spacing={3}>
          {filteredSystems.length === 0 ? (
            <Grid item xs={12}>
              <Paper sx={{ p: 4, textAlign: 'center' }}>
                <Lock sx={{ fontSize: 60, color: 'text.disabled', mb: 2 }} />
                <Typography variant="h6" color="text.secondary">
                  No Systems Assigned
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Contact your administrator to get access to systems
                </Typography>
              </Paper>
            </Grid>
          ) : (
            filteredSystems.map((system) => {
              const isAllowed = allowedSystems.includes(system.id);
              return (
                <Grid item xs={12} sm={6} md={4} lg={3} key={system.id}>
                  <Card 
                    sx={{ 
                      height: '100%', 
                      display: 'flex', 
                      flexDirection: 'column',
                      transition: 'transform 0.2s',
                      '&:hover': isAllowed ? {
                        transform: 'translateY(-5px)',
                        boxShadow: 6
                      } : {},
                      opacity: isAllowed ? 1 : 0.7,
                      position: 'relative'
                    }}
                  >
                    <CardActionArea 
                      onClick={() => handleSystemClick(system)}
                      disabled={!isAllowed}
                      sx={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'flex-start', justifyContent: 'flex-start' }}
                      component="div"
                    >
                      <Box 
                        sx={{ 
                          width: '100%', 
                          p: 3, 
                          background: `linear-gradient(135deg, ${system.color} 0%, ${theme.palette.augmentColor({ color: { main: system.color } }).dark} 100%)`,
                          color: 'white',
                          display: 'flex',
                          justifyContent: 'space-between',
                          alignItems: 'start'
                        }}
                      >
                        <Box sx={{ p: 1, bgcolor: 'rgba(255,255,255,0.2)', borderRadius: 2 }}>
                          {React.cloneElement(system.icon, { sx: { color: 'white' } })}
                        </Box>
                        {!isAllowed && (
                          <Chip 
                            icon={<Lock sx={{ fontSize: '1rem !important', color: 'white !important' }} />} 
                            label="Restricted" 
                            size="small" 
                            sx={{ bgcolor: 'rgba(0,0,0,0.3)', color: 'white' }} 
                          />
                        )}
                      </Box>
                      <CardContent sx={{ flexGrow: 1, width: '100%' }}>
                        <Typography variant="h6" component="div" fontWeight="bold" gutterBottom>
                          {system.name}
                        </Typography>
                        <Typography variant="body2" color="text.secondary">
                          {system.description}
                        </Typography>
                      </CardContent>
                      <Box sx={{ p: 2, width: '100%', pt: 0 }}>
                        <Button 
                          endIcon={isAllowed ? <ArrowForward /> : <Lock />} 
                          fullWidth 
                          variant={isAllowed ? "outlined" : "disabled"}
                          color="primary"
                          sx={{ justifyContent: 'space-between' }}
                        >
                          {isAllowed ? 'Access System' : 'Access Denied'}
                        </Button>
                      </Box>
                    </CardActionArea>
                  </Card>
                </Grid>
              );
            })
          )}
        </Grid>

        <Box sx={{ mt: 8, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 1, color: 'text.secondary' }}>
          <Info fontSize="small" />
          <Typography variant="body2">
            Contact IT Support for system access issues or technical assistance
          </Typography>
        </Box>
      </Container>
      
      <EventGreetingModal 
        open={showGreeting} 
        onClose={() => setShowGreeting(false)}
        event={activeEvent}
      />
      
      <ManageEventsDialog 
        open={showManageEvents} 
        onClose={() => setShowManageEvents(false)} 
      />
    </Box>
  );
};

export default SystemsPortal;
