import React, { useState, useEffect } from 'react';
import { paymentService } from '../../services/paymentService';
import { billingService } from '../../services/billingService';
import { authService } from '../../authService';
import PaymentConfirmDialog from '../common/PaymentConfirmDialog';
import ConfirmationDialog from '../common/ConfirmationDialog';
import BillDetailsModal from '../billing/BillDetailsModal';
import BillModal from '../billing/BillModal';
import {
  Box,
  Container,
  Typography,
  Grid,
  Card,
  CardContent,
  Button,
  TextField,
  InputAdornment,
  IconButton,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Tabs,
  Tab,
  Alert,
  CircularProgress,
  Chip,
  Stack,
  Tooltip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogContentText,
  DialogActions,
  Checkbox,
  Divider,
  TableSortLabel,
  TablePagination
} from '@mui/material';
import {
  Search as SearchIcon,
  Payment as PaymentIcon,
  Add as AddIcon,
  Receipt as ReceiptIcon,
  History as HistoryIcon,
  Print as PrintIcon,
  CheckCircle as CheckCircleIcon,
  CalendarToday as CalendarIcon,
  Person as PersonIcon,
  Clear as ClearIcon,
  Close as CloseIcon,
  Undo as UndoIcon,
  Visibility as VisibilityIcon,
  FilterList as FilterListIcon
} from '@mui/icons-material';

const PaymentsPage = () => {
  const roundTo2 = (num) => Math.round(num * 100) / 100;
  
  const [activeTab, setActiveTab] = useState('search');
  const [searchTerm, setSearchTerm] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [customerTabs, setCustomerTabs] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [showBillModal, setShowBillModal] = useState(false);
  const [billModalMode, setBillModalMode] = useState('add');
  const [selectedBillForModal, setSelectedBillForModal] = useState(null);
  const [preSelectedCustomerForModal, setPreSelectedCustomerForModal] = useState(null);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [billToDelete, setBillToDelete] = useState(null);
  
  // Filters
  const [filterBarangay, setFilterBarangay] = useState('all');
  const [filterType, setFilterType] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');
  const [barangays, setBarangays] = useState([]);
  const [customerTypes, setCustomerTypes] = useState([]);
  const [billCustomerTypes, setBillCustomerTypes] = useState([]);
  
  // Surcharge
  const [surchargeSettings, setSurchargeSettings] = useState(null);
  
  const [stats, setStats] = useState({
    todayCollection: 0,
    todayCount: 0,
    monthCollection: 0,
    monthCount: 0
  });
  
  // Recent Payments
  const [recentPayments, setRecentPayments] = useState([]);
  const [loadingRecentPayments, setLoadingRecentPayments] = useState(false);
  
  // Payment Confirmation
  const [showPaymentConfirm, setShowPaymentConfirm] = useState(false);
  const [pendingPayment, setPendingPayment] = useState(null);
  
  // Mark as Unpaid
  const [showUnpaidConfirm, setShowUnpaidConfirm] = useState(false);
  const [billToMarkUnpaid, setBillToMarkUnpaid] = useState(null);

  // Bill Details Modal
  const [showBillDetails, setShowBillDetails] = useState(false);
  const [selectedBillDetails, setSelectedBillDetails] = useState(null);
  const [loadingBillDetails, setLoadingBillDetails] = useState(false);

  // Auto-Select By Amount
  const [showAutoSelectDialog, setShowAutoSelectDialog] = useState(false);
  const [autoSelectAmount, setAutoSelectAmount] = useState('');

  // Sorting for Payment History
  const [historySortConfig, setHistorySortConfig] = useState({ key: 'datepaid', direction: 'desc' });
  const [historyPage, setHistoryPage] = useState(0);
  const [historyRowsPerPage, setHistoryRowsPerPage] = useState(10);

  const user = authService.getUserSession();

  useEffect(() => {
    const initializeData = async () => {
      loadStats();
      loadFilterOptions();
      const loadedSettings = await loadSurchargeSettings();
      await loadBillCustomerTypes();
      loadRecentPayments();
      
      const preSelectedCustomerData = sessionStorage.getItem('preSelectedCustomerForPayment');
      if (preSelectedCustomerData) {
        try {
          const customer = JSON.parse(preSelectedCustomerData);
          handleSelectCustomer(customer, loadedSettings);
          sessionStorage.removeItem('preSelectedCustomerForPayment');
        } catch (error) {
          console.error('Error parsing preselected customer:', error);
        }
      }
    };
    
    initializeData();
  }, []);
  
  useEffect(() => {
    const handleEditBillEvent = (event) => {
      const billToEdit = event.detail;
      handleEdit(billToEdit);
    };
    const handleDeleteBillEvent = (event) => {
      const billData = event.detail;
      const bill = typeof billData === 'object' ? billData : null;
      if (bill) {
        handleDeleteClick(bill);
      }
    };
    window.addEventListener('editBill', handleEditBillEvent);
    window.addEventListener('deleteBill', handleDeleteBillEvent);
    return () => {
      window.removeEventListener('editBill', handleEditBillEvent);
      window.removeEventListener('deleteBill', handleDeleteBillEvent);
    };
  }, [customerTabs]);

  useEffect(() => {
    if (!searchTerm.trim()) {
      setSearchResults([]);
      return;
    }

    const timer = setTimeout(() => {
      handleSearch();
    }, 500);
    
    return () => clearTimeout(timer);
  }, [searchTerm, filterBarangay, filterType, filterStatus]);

  const loadStats = async () => {
    const result = await paymentService.getPaymentStats();
    if (result.success) {
      setStats(result.data);
    }
  };

  const loadFilterOptions = async () => {
    try {
      const { data: customersData } = await paymentService.searchCustomers('');
      if (customersData) {
        const uniqueBarangays = [...new Set(customersData.map(c => c.barangay).filter(Boolean))];
        setBarangays(uniqueBarangays.map(b => ({ barangay: b })));
        
        const uniqueTypes = [...new Set(customersData.map(c => c.type).filter(Boolean))];
        setCustomerTypes(uniqueTypes.map(t => ({ type: t })));
      }
    } catch (error) {
      console.error('Error loading filter options:', error);
    }
  };

  const loadSurchargeSettings = async () => {
    const result = await paymentService.getSurchargeSettings();
    if (result.success) {
      setSurchargeSettings(result.data);
      return result.data;
    }
    return null;
  };
  
  const loadBillCustomerTypes = async () => {
    const result = await billingService.getCustomerTypes();
    if (result.success) {
      setBillCustomerTypes(result.data);
    }
  };

  const loadRecentPayments = async () => {
    setLoadingRecentPayments(true);
    const result = await paymentService.getRecentPayments(10);
    if (result.success) {
      setRecentPayments(result.data);
    }
    setLoadingRecentPayments(false);
  };

  const handleProcessPayment = async (amountReceived, creditToApply, newCredit, waiveSurcharge = false) => {
    if (!pendingPayment) return;
    
    setLoading(true);
    
    const creditAdjustment = newCredit - creditToApply;
    
    const currentTab = getActiveCustomerTab();
    if (!currentTab) {
      setError('Unable to find customer data');
      setLoading(false);
      return;
    }
    
    // Get selected bills (preserve order from billsWithSurcharge which is sorted by date)
    const selectedBillsData = currentTab.billsWithSurcharge
      .filter(bill => pendingPayment.bills.includes(bill.billid));
      
    let remainingCreditToDistribute = creditToApply;
    
    const billsData = selectedBillsData.map(bill => {
        const surchargeAmount = roundTo2(waiveSurcharge ? 0 : (bill.surchargeInfo?.surchargeAmount || 0));
        const basicAmount = roundTo2(parseFloat(bill.basicamount || 0));
        const discountAmount = roundTo2(bill.calculatedDiscountAmount || 0);
        const totalAmount = roundTo2(basicAmount + surchargeAmount - discountAmount);
        
        // Allocate credit sequentially to selected bills
        let creditForThisBill = 0;
        if (remainingCreditToDistribute > 0) {
          creditForThisBill = Math.min(remainingCreditToDistribute, totalAmount);
          remainingCreditToDistribute = roundTo2(remainingCreditToDistribute - creditForThisBill);
        }
        
        return {
          billid: bill.billid,
          basicamount: basicAmount,
          surchargeamount: surchargeAmount,
          discountamount: discountAmount,
          totalbillamount: totalAmount,
          advancepaymentamount: creditForThisBill
        };
      });
    
    const result = await paymentService.processPayment(
      billsData,
      `${user.firstname} ${user.lastname}`,
      amountReceived,
      creditAdjustment
    );
    
    if (result.success) {
      let message = `Successfully processed payment for ${result.data.paidCount} bill(s)!`;
      if (creditToApply > 0) {
        message += ` Credit of ₱${creditToApply.toFixed(2)} was applied.`;
      }
      if (newCredit > 0) {
        message += ` New credit of ₱${newCredit.toFixed(2)} added to account.`;
      }
      setSuccess(message);
      await reloadCustomerData(pendingPayment.customerid);
      loadStats();
      loadRecentPayments();
      setTimeout(() => setSuccess(''), 5000);
    } else {
      setError(result.error);
    }
    setLoading(false);
    setShowPaymentConfirm(false);
    setPendingPayment(null);
  };

  const handleMarkAsUnpaid = async () => {
    if (!billToMarkUnpaid) return;
    
    setLoading(true);
    const result = await paymentService.markBillAsUnpaid(billToMarkUnpaid.billid);
    
    if (result.success) {
      setSuccess(`Bill #${billToMarkUnpaid.billid} marked as unpaid successfully!`);
      await reloadCustomerData(billToMarkUnpaid.customerid);
      loadStats();
      loadRecentPayments();
      setTimeout(() => setSuccess(''), 3000);
    } else {
      setError(result.error);
    }
    setLoading(false);
    setShowUnpaidConfirm(false);
    setBillToMarkUnpaid(null);
  };

  const getActiveCustomerTab = () => {
    return customerTabs.find(tab => tab.customer.customerid === activeTab);
  };

  const calculateBillsWithSurcharge = (bills, customer, settings = null) => {
    const settingsToUse = settings || surchargeSettings;
    if (!settingsToUse) return bills;
    
    // Sort bills by date (oldest first) to ensure credit applies correctly
    const sortedBills = [...bills].sort((a, b) => new Date(a.billedmonth) - new Date(b.billedmonth));
    
    let remainingCredit = customer ? parseFloat(customer.credit_balance || 0) : 0;
    
    return sortedBills.map(bill => {
      const surchargeInfo = typeof paymentService.calculateSurcharge === 'function'
        ? paymentService.calculateSurcharge(bill, settingsToUse)
        : { surchargeAmount: parseFloat(bill.surchargeamount || 0), daysOverdue: 0 };
      
      const basicAmount = roundTo2(parseFloat(bill.basicamount || 0));
      const surchargeAmount = roundTo2(surchargeInfo ? surchargeInfo.surchargeAmount : parseFloat(bill.surchargeamount || 0));
      
      let calculatedDiscountAmount = 0;
      const consumption = parseFloat(bill.consumption || 0);

      // Discount logic: Only apply if consumption > 1
      if (consumption > 1) {
        if (customer && customer.discount) {
          const customerDiscountPercent = parseFloat(customer.discount);
          calculatedDiscountAmount = roundTo2(((basicAmount + surchargeAmount) * customerDiscountPercent) / 100);
        } else if (bill.discountamount && parseFloat(bill.discountamount) > 0) {
          calculatedDiscountAmount = roundTo2(parseFloat(bill.discountamount));
        }
      }
      
      const totalBeforeCredit = roundTo2(basicAmount + surchargeAmount - calculatedDiscountAmount);
      
      // Apply credit (Oldest bills first)
      let creditApplied = 0;
      if (remainingCredit > 0) {
        creditApplied = Math.min(remainingCredit, totalBeforeCredit);
        remainingCredit = roundTo2(remainingCredit - creditApplied);
      }
      
      const totalAfterCredit = roundTo2(totalBeforeCredit - creditApplied);
      
      return {
        ...bill,
        surchargeInfo,
        calculatedDiscountAmount,
        calculatedTotal: totalBeforeCredit,
        netTotal: totalAfterCredit,
        creditApplied: creditApplied
      };
    });
  };

  const handleSearch = async () => {
    if (!searchTerm.trim()) {
      setError('Please enter a customer name or ID');
      return;
    }

    setLoading(true);
    setError('');
    const result = await paymentService.searchCustomers(searchTerm);
    
    if (result.success) {
      let filteredData = result.data;
      
      if (filterBarangay !== 'all') {
        filteredData = filteredData.filter(c => c.barangay?.toLowerCase() === filterBarangay.toLowerCase());
      }
      if (filterType !== 'all') {
        filteredData = filteredData.filter(c => c.type?.toLowerCase() === filterType.toLowerCase());
      }
      if (filterStatus !== 'all') {
        filteredData = filteredData.filter(c => c.status?.toLowerCase() === filterStatus.toLowerCase());
      }
      
      setSearchResults(filteredData);
      if (filteredData.length === 0) {
        setError(`No customers found matching "${searchTerm}" with current filters.`);
      }
    } else {
      setError(`Search error: ${result.error}`);
    }
    setLoading(false);
  };

  const handleBrowseAll = async () => {
    setLoading(true);
    setError('');
    setSearchTerm('');
    const result = await paymentService.searchCustomers('');
    
    if (result.success) {
      let filteredData = result.data;
      
      if (filterBarangay !== 'all') {
        filteredData = filteredData.filter(c => c.barangay?.toLowerCase() === filterBarangay.toLowerCase());
      }
      if (filterType !== 'all') {
        filteredData = filteredData.filter(c => c.type?.toLowerCase() === filterType.toLowerCase());
      }
      if (filterStatus !== 'all') {
        filteredData = filteredData.filter(c => c.status?.toLowerCase() === filterStatus.toLowerCase());
      }
      
      setSearchResults(filteredData);
      if (filteredData.length === 0) {
        setError('No customers found with current filters.');
      }
    } else {
      setError(`Error loading customers: ${result.error}`);
    }
    setLoading(false);
  };

  const handleSelectCustomer = async (customer, providedSettings = null) => {
    const existingTab = customerTabs.find(tab => tab.customer.customerid === customer.customerid);
    
    if (existingTab) {
      console.error('DEBUG: Tab exists, switching to:', customer.customerid);
      setActiveTab(customer.customerid);
      return;
    }

    setLoading(true);
    setError('');

    try {
      const customerDetailsResult = await paymentService.getCustomerDetails(customer.customerid);
      const customerWithCredit = customerDetailsResult.success ? customerDetailsResult.data : customer;

      const unpaidResult = await paymentService.getUnpaidBills(customer.customerid);
      const unpaidBills = unpaidResult.success ? unpaidResult.data : [];

      const historyResult = await paymentService.getPaymentHistory(customer.customerid);
      const paymentHistory = historyResult.success ? historyResult.data : [];

      const billsWithSurcharge = calculateBillsWithSurcharge(unpaidBills, customerWithCredit, providedSettings);
      const newTab = {
        customer: customerWithCredit,
        unpaidBills,
        paymentHistory,
        billsWithSurcharge,
        selectedBills: [],
        creditBalance: parseFloat(customerWithCredit.credit_balance || 0)
      };

      setCustomerTabs(prev => {
        return [...prev, newTab];
      });
      setActiveTab(customer.customerid);
    } catch (err) {
      console.error('Error in handleSelectCustomer:', err);
      setError('Failed to load customer data');
    } finally {
      setLoading(false);
    }
  };
  
  const openAddModal = (customer = null) => {
    setBillModalMode('add');
    setSelectedBillForModal(null);
    setPreSelectedCustomerForModal(customer);
    setShowBillModal(true);
  };
  
  const handleEdit = (bill) => {
    setBillModalMode('edit');
    setSelectedBillForModal(bill);
    setShowBillModal(true);
  };
  
  const handleDeleteClick = (bill) => {
    setBillToDelete(bill);
    setShowDeleteConfirm(true);
  };
  
  const handleDeleteConfirm = async () => {
    if (!billToDelete) return;
    setLoading(true);
    const result = await billingService.deleteBill(billToDelete.billid);
    if (result.success) {
      setSuccess('Bill deleted successfully');
      await reloadCustomerData(billToDelete.customerid);
      loadStats();
      loadRecentPayments();
      setTimeout(() => setSuccess(''), 3000);
    } else {
      setError(result.error);
    }
    setLoading(false);
    setShowDeleteConfirm(false);
    setBillToDelete(null);
  };
  
  const handleDeleteCancel = () => {
    setShowDeleteConfirm(false);
    setBillToDelete(null);
  };

  const handleCloseTab = (customerid) => {
    const updatedTabs = customerTabs.filter(tab => tab.customer.customerid !== customerid);
    setCustomerTabs(updatedTabs);
    
    if (activeTab === customerid) {
      if (updatedTabs.length > 0) {
        setActiveTab(updatedTabs[updatedTabs.length - 1].customer.customerid);
      } else {
        setActiveTab('search');
      }
    }
  };

  const updateSelectedBills = (bills, autoAmount = null) => {
    setCustomerTabs(prevTabs =>
      prevTabs.map(tab =>
        tab.customer.customerid === activeTab
          ? { ...tab, selectedBills: bills, autoSelectedAmount: autoAmount }
          : tab
      )
    );
  };

  const reloadCustomerData = async (customerid) => {
    const customerDetailsResult = await paymentService.getCustomerDetails(customerid);
    const unpaidResult = await paymentService.getUnpaidBills(customerid);
    const historyResult = await paymentService.getPaymentHistory(customerid);

    const newUnpaidBills = unpaidResult.success ? unpaidResult.data : [];
    const customerWithCredit = customerDetailsResult.success ? customerDetailsResult.data : null;
    const billsWithSurcharge = calculateBillsWithSurcharge(newUnpaidBills, customerWithCredit);

    setCustomerTabs(prevTabs =>
      prevTabs.map(tab =>
        tab.customer.customerid === customerid
          ? {
              ...tab,
              customer: customerWithCredit || tab.customer,
              unpaidBills: newUnpaidBills,
              paymentHistory: historyResult.success ? historyResult.data : [],
              billsWithSurcharge,
              creditBalance: customerWithCredit ? parseFloat(customerWithCredit.credit_balance || 0) : 0,
              selectedBills: []
            }
          : tab
      )
    );
  };
  
  const handleModalSuccess = async (message) => {
    setSuccess(message);
    const customerId =
      preSelectedCustomerForModal?.customerid ||
      selectedBillForModal?.customerid ||
      getActiveCustomerTab()?.customer?.customerid ||
      null;
    if (customerId) {
      await reloadCustomerData(customerId);
    }
    setPreSelectedCustomerForModal(null);
    loadStats();
    loadRecentPayments();
    setTimeout(() => setSuccess(''), 4000);
  };

  const formatCurrency = (amount) => {
    return `₱${parseFloat(amount || 0).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    return new Date(dateString).toLocaleDateString('en-PH', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  const formatMonth = (dateString) => {
    if (!dateString) return 'N/A';
    return new Date(dateString).toLocaleDateString('en-PH', {
      year: 'numeric',
      month: 'long'
    });
  };

  const handleViewBillDetails = async (billid, customerid) => {
    setLoadingBillDetails(true);
    setShowBillDetails(true);
    
    try {
      const customerResult = await paymentService.getCustomerDetails(customerid);
      const customerData = customerResult.success ? customerResult.data : null;

      const billResult = await paymentService.getUnpaidBills(customerid);
      const historyResult = await paymentService.getPaymentHistory(customerid);
      
      let billData = null;
      let isUnpaid = false;
      if (billResult.success) {
        billData = billResult.data.find(b => b.billid === billid);
        if (billData) isUnpaid = true;
      }
      if (!billData && historyResult.success) {
        billData = historyResult.data.find(b => b.billid === billid);
      }

      if (billData && customerData) {
        // We also want to pass the full history to the modal for the graph
        const fullHistory = historyResult.success ? historyResult.data : [];
        
        let enrichedBill = billData;
        
        if (isUnpaid) {
          // For unpaid bills, calculate surcharge and credit allocation
          // Must process ALL unpaid bills to ensure correct "Oldest First" credit application
          const billsWithSurcharge = calculateBillsWithSurcharge(billResult.data, customerData);
          enrichedBill = billsWithSurcharge.find(b => b.billid === billid) || billData;
        } else {
          // For paid bills, use existing data (maybe map fields if necessary for consistency)
          // Ensure creditApplied is present (from advancepaymentamount usually)
          enrichedBill = {
            ...billData,
            creditApplied: billData.advancepaymentamount || 0,
            calculatedTotal: billData.totalbillamount
          };
        }
        
        setSelectedBillDetails({
          bill: enrichedBill,
          customer: customerData,
          history: fullHistory
        });
      } else {
        setError('Unable to load bill details');
        setShowBillDetails(false);
      }
    } catch (error) {
      console.error('Error loading bill details:', error);
      setError('Error loading bill details');
      setShowBillDetails(false);
    }
    
    setLoadingBillDetails(false);
  };

  const handleAutoSelectByAmount = () => {
    const amount = parseFloat(autoSelectAmount);
    if (isNaN(amount) || amount <= 0) {
      setError('Please enter a valid amount');
      return;
    }

    const currentTab = getActiveCustomerTab();
    if (!currentTab) return;

    const { billsWithSurcharge } = currentTab;
    
    // Sort bills by date (oldest first)
    const sortedBills = [...billsWithSurcharge].sort((a, b) => {
      const dateA = new Date(a.billedmonth);
      const dateB = new Date(b.billedmonth);
      return dateA - dateB;
    });

    let remainingAmount = amount;
    const billsToSelect = [];
    const selectedMonths = [];
    let nextBillMonth = null;

    for (const bill of sortedBills) {
      // Calculate total amount for this bill including surcharge
      // Logic mirrors the calculation in the table
      const surcharge = bill.surchargeInfo?.surchargeAmount || 0;
      const basic = parseFloat(bill.basicamount || 0);
      const discount = parseFloat(bill.calculatedDiscountAmount || 0); // Assuming discount logic exists or included in netTotal
      
      // Use netTotal if available, otherwise calculatedTotal, otherwise basic+surcharge
      // Note: In the table, we use bill.netTotal !== undefined ? bill.netTotal : (bill.calculatedTotal || bill.totalbillamount)
      // However, netTotal might already include credit deduction if we implemented it in state.
      // But for selection purposes, we care about the amount *to be paid*.
      // If credit is already applied, netTotal is the remaining to pay.
      // Let's rely on netTotal which should be the source of truth for "Amount Due".
      
      const billTotal = parseFloat(bill.netTotal !== undefined ? bill.netTotal : (bill.calculatedTotal || bill.totalbillamount));
      
      if (remainingAmount >= billTotal) {
        billsToSelect.push(bill.billid);
        selectedMonths.push(formatMonth(bill.billedmonth));
        remainingAmount -= billTotal;
      } else {
        // Amount insufficient to cover this bill fully
        // Stop selection as per "oldest first" rule
        nextBillMonth = formatMonth(bill.billedmonth);
        break;
      }
    }

    if (billsToSelect.length > 0) {
      updateSelectedBills(billsToSelect, amount);
      
      let message = `Automatically selected ${billsToSelect.length} bill(s)`;
      if (selectedMonths.length > 0) {
        message += ` covering ${selectedMonths.join(', ')}`;
      }
      message += `.`;
      
      if (remainingAmount > 0) {
        if (nextBillMonth) {
           message += ` Remaining amount of ${formatCurrency(remainingAmount)} will be applied on ${nextBillMonth}.`;
        } else {
           message += ` Remaining amount: ${formatCurrency(remainingAmount)}.`;
        }
      }

      setSuccess(message);
      setShowAutoSelectDialog(false);
      setAutoSelectAmount('');
    } else {
      setError('Amount is insufficient to cover the oldest unpaid bill.');
    }
  };

  const handleHistorySort = (key) => {
    let direction = 'asc';
    if (historySortConfig.key === key && historySortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setHistorySortConfig({ key, direction });
  };

  const getSortedHistory = (history) => {
    if (!history) return [];
    
    const sorted = [...history].sort((a, b) => {
      let aValue = a[historySortConfig.key];
      let bValue = b[historySortConfig.key];
      
      // Handle special cases
      if (historySortConfig.key === 'amount') {
        aValue = parseFloat(a.totalbillamount || 0);
        bValue = parseFloat(b.totalbillamount || 0);
      } else if (historySortConfig.key === 'consumption') {
        aValue = parseFloat(a.consumption || 0);
        bValue = parseFloat(b.consumption || 0);
      }
      
      if (aValue < bValue) return historySortConfig.direction === 'asc' ? -1 : 1;
      if (aValue > bValue) return historySortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
    
    return sorted;
  };

  const handlePrintSelectedBills = () => {
    const currentTab = getActiveCustomerTab();
    if (!currentTab || !currentTab.selectedBills || currentTab.selectedBills.length === 0) {
      setError('No bills selected for printing');
      setTimeout(() => setError(''), 3000);
      return;
    }

    const { customer, billsWithSurcharge, selectedBills } = currentTab;
    const selectedBillsData = billsWithSurcharge.filter(bill => selectedBills.includes(bill.billid));
    
    const totalBasic = selectedBillsData.reduce((sum, bill) => sum + parseFloat(bill.basicamount || 0), 0);
    const totalSurcharge = selectedBillsData.reduce((sum, bill) => sum + parseFloat(bill.surchargeInfo?.surchargeAmount || 0), 0);
    const totalDiscount = selectedBillsData.reduce((sum, bill) => sum + parseFloat(bill.calculatedDiscountAmount || 0), 0);
    const totalCredit = selectedBillsData.reduce((sum, bill) => sum + parseFloat(bill.creditApplied || 0), 0);
    const grandTotal = selectedBillsData.reduce((sum, bill) => sum + parseFloat(bill.netTotal !== undefined ? bill.netTotal : (bill.calculatedTotal || bill.totalbillamount || 0)), 0);

    const currentDate = new Date().toLocaleDateString('en-PH', { 
      year: 'numeric', month: 'long', day: 'numeric', 
      hour: '2-digit', minute: '2-digit' 
    });

    const openFn = typeof globalThis.open === 'function' ? globalThis.open : window.open;

    let printWindow = null;
    try {
      printWindow = openFn('', '', 'width=900,height=700');
    } catch (e) {
      console.error('Error opening print window:', e);
      printWindow = null;
    }

    if (!printWindow || !printWindow.document) {
      console.error('Print window or document not available');
      setError('Unable to open print window. Please allow pop-ups and try again.');
      return;
    }
    printWindow.document.write(`
      <!DOCTYPE html>
      <html>
      <head>
        <title>Billing Statement - ${customer.name}</title>
        <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
        <style>
          :root {
            --primary-color: #0f172a;
            --secondary-color: #64748b;
            --accent-color: #0ea5e9;
            --danger-color: #ef4444;
            --success-color: #10b981;
            --border-color: #e2e8f0;
            --bg-subtle: #f8fafc;
          }
          
          body { 
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            color: var(--primary-color);
            line-height: 1.5;
            margin: 0;
            padding: 40px;
            font-size: 14px;
            -webkit-print-color-adjust: exact;
            print-color-adjust: exact;
          }

          .header { 
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
            margin-bottom: 40px;
            padding-bottom: 20px;
            border-bottom: 2px solid var(--primary-color);
          }

          .company-info h1 {
            margin: 0;
            font-size: 24px;
            font-weight: 800;
            letter-spacing: -0.5px;
            text-transform: uppercase;
          }

          .company-info p {
            margin: 4px 0 0;
            color: var(--secondary-color);
            font-size: 13px;
          }

          .document-title {
            text-align: right;
          }

          .document-title h2 {
            margin: 0;
            font-size: 18px;
            font-weight: 600;
            color: var(--secondary-color);
            text-transform: uppercase;
            letter-spacing: 1px;
          }

          .document-title p {
            margin: 4px 0 0;
            font-size: 13px;
            color: var(--secondary-color);
          }

          .customer-section {
            background-color: var(--bg-subtle);
            border-radius: 8px;
            padding: 24px;
            margin-bottom: 32px;
            border: 1px solid var(--border-color);
          }

          .info-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 24px;
          }

          .info-group label {
            display: block;
            font-size: 11px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            color: var(--secondary-color);
            margin-bottom: 4px;
            font-weight: 600;
          }

          .info-group div {
            font-weight: 500;
            font-size: 15px;
          }

          table {
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 32px;
          }

          th {
            background-color: var(--bg-subtle);
            padding: 12px 16px;
            text-align: left;
            font-weight: 600;
            font-size: 12px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            color: var(--secondary-color);
            border-bottom: 1px solid var(--border-color);
          }

          td {
            padding: 16px;
            border-bottom: 1px solid var(--border-color);
            vertical-align: middle;
          }

          .text-right { text-align: right; }
          .text-center { text-align: center; }
          
          .amount-cell {
            font-family: 'Roboto Mono', monospace;
            font-weight: 500;
          }

          .tag {
            display: inline-block;
            padding: 2px 8px;
            border-radius: 4px;
            font-size: 11px;
            font-weight: 600;
          }

          .tag-red { background-color: #fee2e2; color: #991b1b; }
          .tag-green { background-color: #d1fae5; color: #065f46; }

          .summary-section {
            display: flex;
            justify-content: flex-end;
          }

          .summary-table {
            width: 300px;
          }

          .summary-row {
            display: flex;
            justify-content: space-between;
            padding: 8px 0;
            font-size: 13px;
            color: var(--secondary-color);
          }

          .summary-row.total {
            border-top: 2px solid var(--primary-color);
            margin-top: 8px;
            padding-top: 16px;
            font-size: 18px;
            font-weight: 700;
            color: var(--primary-color);
          }

          .credit-note {
            font-size: 11px;
            color: var(--success-color);
            margin-top: 2px;
          }

          .footer {
            margin-top: 60px;
            text-align: center;
            font-size: 12px;
            color: var(--secondary-color);
            border-top: 1px solid var(--border-color);
            padding-top: 20px;
          }

          @media print {
            body { padding: 0; }
            .customer-section { -webkit-print-color-adjust: exact; }
          }
        </style>
      </head>
      <body>
        <div class="header">
          <div class="company-info">
            <h1>Water Billing System</h1>
            <p>Official Statement of Account</p>
          </div>
          <div class="document-title">
            <h2>Payment Selection</h2>
            <p>Generated: ${currentDate}</p>
          </div>
        </div>

        <div class="customer-section">
          <div style="display: flex; justify-content: space-between; align-items: flex-start;">
             <div>
                <div style="font-size: 16px; font-weight: 700; margin-bottom: 4px;">${customer.name}</div>
                <div style="color: var(--secondary-color); font-size: 13px;">
                   ID: ${customer.customerid} &nbsp;•&nbsp; ${customer.type} &nbsp;•&nbsp; ${customer.address || customer.barangay || 'No Address'}
                </div>
             </div>
             <div style="text-align: right;">
                <div class="tag ${customer.status === 'Active' ? 'tag-green' : 'tag-red'}">${customer.status}</div>
             </div>
          </div>
          ${customer.remarks ? `
          <div style="margin-top: 12px; padding-top: 12px; border-top: 1px dashed var(--border-color); font-size: 12px; color: var(--secondary-color);">
             <span style="font-weight: 600; text-transform: uppercase; font-size: 11px;">Remarks:</span> ${customer.remarks}
          </div>
          ` : ''}
        </div>

        <table>
          <thead>
            <tr>
              <th>Bill ID</th>
              <th>Billing Period</th>
              <th class="text-right">Consumption</th>
              <th class="text-right">Basic Amount</th>
              <th class="text-center">Adjustments</th>
              <th class="text-right">Total</th>
            </tr>
          </thead>
          <tbody>
            ${selectedBillsData.map(bill => {
              const surAmount = bill.surchargeInfo?.surchargeAmount || 0;
              const discAmount = bill.calculatedDiscountAmount || 0;
              
              let adjustments = [];
              if (surAmount > 0) adjustments.push(`<span class="tag tag-red">Sur: ${formatCurrency(surAmount)}</span>`);
              if (discAmount > 0) adjustments.push(`<span class="tag tag-green">Disc: ${formatCurrency(discAmount)}</span>`);
              
              return `
              <tr>
                <td>#${bill.billid}</td>
                <td>${formatMonth(bill.billedmonth)}</td>
                <td class="text-right">${bill.consumption} m³</td>
                <td class="text-right amount-cell">
                  ${formatCurrency(bill.basicamount)}
                  ${bill.creditApplied > 0 ? `<div class="credit-note">-${formatCurrency(bill.creditApplied)} Credit</div>` : ''}
                </td>
                <td class="text-center">${adjustments.length > 0 ? adjustments.join(' ') : '<span style="color: #cbd5e1">—</span>'}</td>
                <td class="text-right amount-cell">${formatCurrency(bill.netTotal !== undefined ? bill.netTotal : (bill.calculatedTotal || bill.totalbillamount))}</td>
              </tr>
              `;
            }).join('')}
          </tbody>
        </table>

        <div class="summary-section">
          <div class="summary-table">
            <div class="summary-row">
              <span>Subtotal (Basic)</span>
              <span>${formatCurrency(totalBasic)}</span>
            </div>
            ${totalSurcharge > 0 ? `
            <div class="summary-row">
              <span>Total Surcharge</span>
              <span>${formatCurrency(totalSurcharge)}</span>
            </div>` : ''}
            ${totalDiscount > 0 ? `
            <div class="summary-row">
              <span>Total Discount</span>
              <span>-${formatCurrency(totalDiscount)}</span>
            </div>` : ''}
            ${totalCredit > 0 ? `
            <div class="summary-row">
              <span>Credit Applied</span>
              <span style="color: var(--success-color)">-${formatCurrency(totalCredit)}</span>
            </div>` : ''}
            <div class="summary-row total">
              <span>Total Amount Due</span>
              <span>${formatCurrency(grandTotal)}</span>
            </div>
          </div>
        </div>

        <div class="footer">
          <p>This is a system generated report. For questions, please contact the administration.</p>
        </div>

        <script>
          window.onload = function() { window.print(); }
        </script>
      </body>
      </html>
    `);
    printWindow.document.close();
  };

  return (
    <Box sx={{ flexGrow: 1 }}>
      <Container maxWidth="xl" sx={{ p: 0 }}>
        {/* Header */}
        <Box sx={{ mb: 3 }}>
          <Typography variant="h5" component="h1" fontWeight="bold" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <PaymentIcon color="primary" /> Payment Processing
          </Typography>
          <Grid container spacing={2} sx={{ mt: 2 }}>
            <Grid item xs={12} sm={4}>
              <Card sx={{ bgcolor: 'info.lighter' }}>
                <CardContent>
                  <Typography variant="subtitle2" color="info.dark">Today's Collection</Typography>
                  <Typography variant="h5" fontWeight="bold" color="info.main">{formatCurrency(stats.todayCollection)}</Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} sm={4}>
              <Card sx={{ bgcolor: 'success.lighter' }}>
                <CardContent>
                  <Typography variant="subtitle2" color="success.dark">Month's Collection</Typography>
                  <Typography variant="h5" fontWeight="bold" color="success.main">{formatCurrency(stats.monthCollection)}</Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} sm={4}>
              <Card sx={{ bgcolor: 'warning.lighter' }}>
                <CardContent>
                  <Typography variant="subtitle2" color="warning.dark">Total Transactions</Typography>
                  <Typography variant="h5" fontWeight="bold" color="warning.main">{stats.todayCount + stats.monthCount}</Typography>
                </CardContent>
              </Card>
            </Grid>
          </Grid>
        </Box>

        {/* Alerts */}
        {error && <Alert severity="error" onClose={() => setError('')} sx={{ mb: 2 }}>{error}</Alert>}
        {success && <Alert severity="success" onClose={() => setSuccess('')} sx={{ mb: 2 }}>{success}</Alert>}

        {/* Tabs */}
        <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
          <Tabs 
            value={activeTab} 
            onChange={(e, v) => setActiveTab(v)} 
            variant="scrollable" 
            scrollButtons="auto"
          >
            <Tab icon={<SearchIcon />} iconPosition="start" label="Customer Search" value="search" />
            {customerTabs.map(tab => (
              <Tab 
                key={tab.customer.customerid} 
                label={
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    {tab.customer.name}
                    <Box 
                      component="span"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleCloseTab(tab.customer.customerid);
                      }}
                      sx={{ 
                        p: 0.5, 
                        ml: 1, 
                        cursor: 'pointer', 
                        display: 'inline-flex',
                        alignItems: 'center',
                        borderRadius: '50%',
                        '&:hover': { bgcolor: 'rgba(0, 0, 0, 0.04)' }
                      }}
                    >
                      <CloseIcon fontSize="small" />
                    </Box>
                  </Box>
                } 
                value={tab.customer.customerid} 
              />
            ))}
          </Tabs>
        </Box>

        {/* Search Tab */}
        {activeTab === 'search' && (
          <Box>
            <Card variant="outlined" sx={{ mb: 3 }}>
              <CardContent>
                <Grid container spacing={2} alignItems="center">
                  <Grid item xs={12} md={6}>
                    <TextField
                      fullWidth
                      placeholder="Search customer name or ID..."
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                      InputProps={{
                        startAdornment: <InputAdornment position="start"><SearchIcon /></InputAdornment>,
                        endAdornment: (
                          <InputAdornment position="end">
                            <Button variant="contained" size="small" onClick={handleSearch} disabled={loading}>Search</Button>
                          </InputAdornment>
                        )
                      }}
                      size="small"
                    />
                  </Grid>
                  {/* Filter Selects */}
                  <Grid item xs={12} md={2}>
                    <FormControl fullWidth size="small">
                      <Select value={filterBarangay} onChange={(e) => setFilterBarangay(e.target.value)}>
                        <MenuItem value="all">All Barangays</MenuItem>
                        {barangays.map(b => <MenuItem key={b.barangay} value={b.barangay}>{b.barangay}</MenuItem>)}
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={12} md={2}>
                    <FormControl fullWidth size="small">
                      <Select value={filterType} onChange={(e) => setFilterType(e.target.value)}>
                        <MenuItem value="all">All Types</MenuItem>
                        {customerTypes.map(t => <MenuItem key={t.type} value={t.type}>{t.type}</MenuItem>)}
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={12} md={2}>
                    <Button variant="outlined" fullWidth onClick={handleBrowseAll} disabled={loading}>Browse All</Button>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>

            {searchResults.length > 0 && (
              <Card variant="outlined" sx={{ mb: 3 }}>
                <CardContent>
                  <Typography variant="h6" gutterBottom>Search Results</Typography>
                  <TableContainer>
                    <Table size="small">
                      <TableHead>
                        <TableRow>
                          <TableCell>ID</TableCell>
                          <TableCell>Name</TableCell>
                          <TableCell>Type</TableCell>
                          <TableCell>Barangay</TableCell>
                          <TableCell>Status</TableCell>
                          <TableCell>Action</TableCell>
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {searchResults.map(customer => (
                          <TableRow key={customer.customerid} hover onClick={() => handleSelectCustomer(customer)} sx={{ cursor: 'pointer' }}>
                            <TableCell>{customer.customerid}</TableCell>
                            <TableCell fontWeight="bold">{customer.name}</TableCell>
                            <TableCell><Chip label={customer.type} size="small" variant="outlined" /></TableCell>
                            <TableCell>{customer.barangay}</TableCell>
                            <TableCell><Chip label={customer.status} color={customer.status === 'Active' ? 'success' : 'error'} size="small" /></TableCell>
                            <TableCell>
                              <Stack direction="row" spacing={1}>
                                <Button size="small" variant="contained" onClick={(e) => { e.stopPropagation(); handleSelectCustomer(customer); }}>
                                  Select
                                </Button>
                                <Button
                                  size="small"
                                  variant="outlined"
                                  startIcon={<AddIcon />}
                                  onClick={(e) => { e.stopPropagation(); openAddModal(customer); }}
                                >
                                  Add Bill
                                </Button>
                              </Stack>
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </TableContainer>
                </CardContent>
              </Card>
            )}

            {recentPayments.length > 0 && (
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="h6" gutterBottom>Recent Payments</Typography>
                  <TableContainer>
                    <Table size="small">
                      <TableHead>
                        <TableRow>
                          <TableCell>Date Paid</TableCell>
                          <TableCell>Customer</TableCell>
                          <TableCell>Month</TableCell>
                          <TableCell>Amount</TableCell>
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {recentPayments.map(payment => (
                          <TableRow key={payment.billid} hover onClick={() => handleViewBillDetails(payment.billid, payment.customerid)} sx={{ cursor: 'pointer' }}>
                            <TableCell>{formatDate(payment.datepaid)}</TableCell>
                            <TableCell>
                              <Typography variant="body2" fontWeight="bold">{payment.customer?.name}</Typography>
                              <Typography variant="caption">{payment.customerid}</Typography>
                            </TableCell>
                            <TableCell>{formatMonth(payment.billedmonth)}</TableCell>
                            <TableCell sx={{ color: 'success.main', fontWeight: 'bold' }}>{formatCurrency(payment.totalbillamount)}</TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </TableContainer>
                </CardContent>
              </Card>
            )}
          </Box>
        )}

        {/* Customer Tab Content */}
        {activeTab !== 'search' && getActiveCustomerTab() && (() => {
          const currentTab = getActiveCustomerTab();
          const { customer, unpaidBills, paymentHistory, billsWithSurcharge, selectedBills } = currentTab;
          
          return (
            <Stack spacing={3}>
          {/* Customer Info - Minimal Version */}
              <Card variant="outlined" sx={{ borderRadius: 2, mb: 2 }}>
                <CardContent sx={{ p: 2, '&:last-child': { pb: 2 } }}>
                  <Grid container spacing={2} alignItems="center">
                    {/* Left Side: Basic Info */}
                    <Grid item xs={12} md={8}>
                      <Box sx={{ display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: 1.5, mb: 0.5 }}>
                        <Typography variant="h6" fontWeight="bold" sx={{ lineHeight: 1.2 }}>
                          {customer.name}
                        </Typography>
                        <Chip 
                          label={`ID: ${customer.customerid}`} 
                          size="small" 
                          variant="outlined" 
                          sx={{ borderRadius: 1, height: 22, fontSize: '0.75rem' }} 
                        />
                        <Chip 
                          label={customer.status} 
                          color={customer.status === 'Active' ? 'success' : 'error'} 
                          size="small"
                          sx={{ height: 22, fontWeight: 'bold', fontSize: '0.75rem' }}
                        />
                      </Box>
                      
                      <Stack direction="row" spacing={2} divider={<Divider orientation="vertical" flexItem />} sx={{ mb: 0.5, flexWrap: 'wrap', gap: 0.5 }}>
                        <Typography variant="body2" color="text.secondary">
                          {customer.type || 'N/A'}
                        </Typography>
                        <Typography variant="body2" color="text.secondary">
                          {customer.barangay || 'N/A'}
                        </Typography>
                        {customer.discount && (
                          <Typography variant="body2" color="success.main" fontWeight="medium">
                            Disc: {customer.discount}%
                          </Typography>
                        )}
                        {customer.status === 'Disconnected' && (
                          <Typography variant="body2" color="error" fontWeight="medium">
                             Disc. Date: {formatDate(customer.disconnection_date)}
                          </Typography>
                        )}
                      </Stack>
                      
                      {/* Remarks - Only if present */}
                      {(customer.remarks) && (
                         <Typography variant="body2" sx={{ fontStyle: 'italic', color: 'text.secondary', display: 'flex', alignItems: 'center', gap: 0.5, mt: 0.5 }}>
                           <span style={{ fontWeight: 600, fontStyle: 'normal', fontSize: '0.75rem', textTransform: 'uppercase' }}>Remarks:</span> {customer.remarks}
                         </Typography>
                      )}
                    </Grid>

                    {/* Right Side: Credit Balance */}
                    <Grid item xs={12} md={4} sx={{ display: 'flex', justifyContent: { xs: 'flex-start', md: 'flex-end' }, alignItems: 'center' }}>
                      <Box sx={{ textAlign: { xs: 'left', md: 'right' } }}>
                        <Typography variant="caption" color="text.secondary" display="block" sx={{ fontSize: '0.7rem', textTransform: 'uppercase', letterSpacing: 0.5 }}>CREDIT BALANCE</Typography>
                        <Typography variant="h4" color="success.main" fontWeight="bold">
                          {formatCurrency(currentTab.creditBalance)}
                        </Typography>
                      </Box>
                    </Grid>
                  </Grid>
                </CardContent>
              </Card>

              {/* Unpaid Bills */}
              <Card variant="outlined">
                <CardContent>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                      <Typography variant="h6">
                        Unpaid Bills 
                        {unpaidBills.length > 0 && <Chip label={unpaidBills.length} color="error" size="small" sx={{ ml: 1 }} />}
                      </Typography>
                    </Box>
                    <Stack direction="row" spacing={1}>
                      {selectedBills.length === 0 && unpaidBills.length > 0 && (
                        <Button 
                          variant="outlined" 
                          size="small" 
                          onClick={() => setShowAutoSelectDialog(true)}
                          startIcon={<PaymentIcon />}
                        >
                          Auto-Select by Amount
                        </Button>
                      )}
                      <Button 
                        variant="contained"
                        size="small"
                        startIcon={<AddIcon />}
                        onClick={() => openAddModal(customer)}
                      >
                        Add Bill
                      </Button>
                    </Stack>
                  </Box>
                  
                  {unpaidBills.length === 0 ? (
                    <Alert severity="success">No unpaid bills</Alert>
                  ) : (
                    <TableContainer>
                      <Table size="small">
                        <TableHead>
                          <TableRow>
                            <TableCell padding="checkbox">
                              <Checkbox 
                                checked={selectedBills.length === billsWithSurcharge.length && billsWithSurcharge.length > 0}
                                onChange={(e) => {
                                  if (e.target.checked) updateSelectedBills(billsWithSurcharge.map(b => b.billid));
                                  else updateSelectedBills([]);
                                }}
                              />
                            </TableCell>
                            <TableCell>Bill ID</TableCell>
                            <TableCell>Month</TableCell>
                            <TableCell align="right">Prev Read</TableCell>
                            <TableCell align="right">Curr Read</TableCell>
                            <TableCell align="right">Cons.</TableCell>
                            <TableCell align="right">Basic</TableCell>
                            <TableCell align="center">Surcharge/Discount</TableCell>
                            <TableCell align="right">Total</TableCell>
                            <TableCell>Status</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {billsWithSurcharge.map(bill => (
                            <TableRow 
                              key={bill.billid} 
                              hover 
                              selected={selectedBills.includes(bill.billid)}
                              title={bill.reader ? `Reader: ${bill.reader}` : ''}
                            >
                              <TableCell padding="checkbox">
                                <Checkbox 
                                  checked={selectedBills.includes(bill.billid)}
                                  onChange={(e) => {
                                    if (e.target.checked) updateSelectedBills([...selectedBills, bill.billid]);
                                    else updateSelectedBills(selectedBills.filter(id => id !== bill.billid));
                                  }}
                                />
                              </TableCell>
                              <TableCell>{bill.billid}</TableCell>
                              <TableCell>
                                {formatMonth(bill.billedmonth)}
                                {bill.surchargeInfo?.daysOverdue > 0 && (
                                  <Typography variant="caption" display="block" color="error">
                                    {bill.surchargeInfo.daysOverdue} days overdue
                                  </Typography>
                                )}
                              </TableCell>
                              <TableCell align="right">{bill.previousreading}</TableCell>
                              <TableCell align="right">{bill.currentreading}</TableCell>
                              <TableCell align="right">{bill.consumption}</TableCell>
                              <TableCell align="right">
                              {formatCurrency(bill.basicamount)}
                              {bill.creditApplied > 0 && (
                                <>
                                  <Typography variant="caption" display="block" color="success.main" sx={{ fontSize: '0.7rem' }}>
                                    - {formatCurrency(bill.creditApplied)} (Credit)
                                  </Typography>
                                  <Divider sx={{ my: 0.5, opacity: 0.6 }} />
                                  <Typography variant="caption" display="block" fontWeight="bold" sx={{ fontSize: '0.75rem' }}>
                                    {formatCurrency(parseFloat(bill.basicamount || 0) - parseFloat(bill.creditApplied || 0))}
                                  </Typography>
                                </>
                              )}
                            </TableCell>
                            <TableCell align="center">
                              <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 0.5, whiteSpace: 'nowrap' }}>
                                {(bill.surchargeInfo?.surchargeAmount > 0 || bill.calculatedDiscountAmount > 0) ? (
                                  <>
                                    {bill.surchargeInfo?.surchargeAmount > 0 && (
                                      <Typography variant="body2" color="error.main" fontWeight="bold">
                                        Sur: {formatCurrency(bill.surchargeInfo.surchargeAmount)}
                                      </Typography>
                                    )}
                                    
                                    {bill.surchargeInfo?.surchargeAmount > 0 && bill.calculatedDiscountAmount > 0 && (
                                       <Typography variant="body2" color="text.secondary" sx={{ mx: 0.5 }}>/</Typography>
                                    )}

                                    {bill.calculatedDiscountAmount > 0 && (
                                      <Typography variant="body2" color="success.main" fontWeight="bold">
                                        Disc: {formatCurrency(bill.calculatedDiscountAmount)}
                                      </Typography>
                                    )}
                                  </>
                                ) : (
                                  <Typography variant="body2" color="text.secondary">-</Typography>
                                )}
                              </Box>
                            </TableCell>
                            <TableCell align="right" fontWeight="bold">
                              {formatCurrency(bill.netTotal !== undefined ? bill.netTotal : (bill.calculatedTotal || bill.totalbillamount))}
                              {bill.creditApplied > 0 && (
                                <Typography variant="caption" display="block" color="text.secondary" sx={{ textDecoration: 'line-through', fontSize: '0.7rem' }}>
                                  {formatCurrency(bill.calculatedTotal || bill.totalbillamount)}
                                </Typography>
                              )}
                            </TableCell>
                              <TableCell><Chip label={bill.paymentstatus} size="small" color={bill.paymentstatus === 'Unpaid' ? 'error' : 'warning'} /></TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </TableContainer>
                  )}
                  
                  {selectedBills.length > 0 && (
                    <Box sx={{ mt: 2 }}>
                      <Paper variant="outlined" sx={{ p: 2, bgcolor: 'grey.50', mb: 2 }}>
                        <Typography variant="subtitle2" fontWeight="bold" gutterBottom>Selected Bills Summary</Typography>
                        <Grid container spacing={2}>
                          <Grid item xs={6} md={2}>
                            <Typography variant="caption" color="text.secondary">Total Basic</Typography>
                            <Typography variant="subtitle1" fontWeight="bold">
                              {formatCurrency(billsWithSurcharge.filter(b => selectedBills.includes(b.billid)).reduce((sum, b) => sum + parseFloat(b.basicamount || 0), 0))}
                            </Typography>
                          </Grid>
                          <Grid item xs={6} md={2}>
                            <Typography variant="caption" color="text.secondary">Surcharge</Typography>
                            <Typography variant="subtitle1" fontWeight="bold" color="error.main">
                              {formatCurrency(billsWithSurcharge.filter(b => selectedBills.includes(b.billid)).reduce((sum, b) => sum + parseFloat(b.surchargeInfo?.surchargeAmount || 0), 0))}
                            </Typography>
                          </Grid>
                          <Grid item xs={6} md={2}>
                            <Typography variant="caption" color="text.secondary">Discount</Typography>
                            <Typography variant="subtitle1" fontWeight="bold" color="success.main">
                              -{formatCurrency(billsWithSurcharge.filter(b => selectedBills.includes(b.billid)).reduce((sum, b) => sum + parseFloat(b.calculatedDiscountAmount || 0), 0))}
                            </Typography>
                          </Grid>
                          <Grid item xs={6} md={3}>
                            <Typography variant="caption" color="text.secondary">Credit Applied</Typography>
                            <Typography variant="subtitle1" fontWeight="bold" color="info.main">
                              -{formatCurrency(billsWithSurcharge.filter(b => selectedBills.includes(b.billid)).reduce((sum, b) => sum + parseFloat(b.creditApplied || 0), 0))}
                            </Typography>
                          </Grid>
                          <Grid item xs={6} md={3}>
                            <Typography variant="caption" color="text.secondary">Net Payable</Typography>
                            <Typography variant="h5" color="primary.main" fontWeight="bold">
                              {formatCurrency(billsWithSurcharge.filter(b => selectedBills.includes(b.billid)).reduce((sum, b) => sum + parseFloat(b.netTotal !== undefined ? b.netTotal : (b.calculatedTotal || b.totalbillamount || 0)), 0))}
                            </Typography>
                          </Grid>
                        </Grid>
                      </Paper>
                      <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 2 }}>
                        <Button variant="outlined" onClick={() => updateSelectedBills([])}>Clear Selection</Button>
                        <Button variant="contained" color="info" onClick={handlePrintSelectedBills}>Print Bills</Button>
                        <Button 
                          variant="contained" 
                          color="success"
                          onClick={() => {
                            const selectedBillsData = billsWithSurcharge.filter(bill => selectedBills.includes(bill.billid));
                            const totalAmount = roundTo2(selectedBillsData.reduce((sum, bill) => sum + parseFloat(bill.calculatedTotal || bill.totalbillamount || 0), 0));
                            const totalSurcharge = roundTo2(selectedBillsData.reduce((sum, bill) => sum + parseFloat(bill.surchargeInfo?.surchargeAmount || 0), 0));
                            const totalCreditAllocated = roundTo2(selectedBillsData.reduce((sum, bill) => sum + parseFloat(bill.creditApplied || 0), 0));
                            
                            setPendingPayment({
                              bills: selectedBills,
                              customerid: customer.customerid,
                              count: selectedBills.length,
                              totalAmount,
                              totalSurcharge,
                              creditBalance: totalCreditAllocated,
                              autoSelectedAmount: currentTab.autoSelectedAmount // Pass the auto-selected amount from tab state
                            });
                            setShowPaymentConfirm(true);
                          }}
                        >
                          Process Payment
                        </Button>
                      </Box>
                    </Box>
                  )}
                </CardContent>
              </Card>

              {/* Payment History */}
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="h6" gutterBottom>Payment History</Typography>
                  {paymentHistory.length > 0 && (() => {
                    const totalsByDate = paymentHistory.reduce((acc, bill) => {
                      const d = bill.datepaid || '';
                      const key = d ? new Date(d).toISOString().split('T')[0] : '';
                      if (!key) return acc;
                      const prev = acc.get(key) || 0;
                      acc.set(key, prev + parseFloat(bill.totalbillamount || 0));
                      return acc;
                    }, new Map());
                    const summary = Array.from(totalsByDate.entries())
                      .sort((a, b) => new Date(b[0]) - new Date(a[0]))
                      .slice(0, 7);
                    return (
                      <Paper variant="outlined" sx={{ p: 1.5, mb: 2, bgcolor: 'grey.50' }}>
                        <Typography variant="subtitle2" sx={{ mb: 1 }} fontWeight="bold">Daily Totals</Typography>
                        <Stack direction="row" spacing={1} flexWrap="wrap">
                          {summary.map(([date, amt]) => (
                            <Chip key={date} label={`${date} • ${formatCurrency(amt)}`} size="small" sx={{ borderRadius: 1 }} />
                          ))}
                        </Stack>
                      </Paper>
                    );
                  })()}
                  {paymentHistory.length === 0 ? (
                    <Alert severity="info">No payment history</Alert>
                  ) : (
                    <TableContainer>
                      <Table size="small">
                        <TableHead>
                          <TableRow>
                            <TableCell>
                              <TableSortLabel 
                                active={historySortConfig.key === 'billedmonth'} 
                                direction={historySortConfig.key === 'billedmonth' ? historySortConfig.direction : 'asc'}
                                onClick={() => handleHistorySort('billedmonth')}
                              >
                                Period
                              </TableSortLabel>
                            </TableCell>
                            <TableCell align="right">Prev Read</TableCell>
                            <TableCell align="right">Curr Read</TableCell>
                            <TableCell align="right">
                              <TableSortLabel 
                                active={historySortConfig.key === 'consumption'} 
                                direction={historySortConfig.key === 'consumption' ? historySortConfig.direction : 'asc'}
                                onClick={() => handleHistorySort('consumption')}
                              >
                                Cons.
                              </TableSortLabel>
                            </TableCell>
                            <TableCell>
                              <TableSortLabel 
                                active={historySortConfig.key === 'datepaid'} 
                                direction={historySortConfig.key === 'datepaid' ? historySortConfig.direction : 'asc'}
                                onClick={() => handleHistorySort('datepaid')}
                              >
                                Date Paid
                              </TableSortLabel>
                            </TableCell>
                            <TableCell align="right">
                              <TableSortLabel 
                                active={historySortConfig.key === 'amount'} 
                                direction={historySortConfig.key === 'amount' ? historySortConfig.direction : 'asc'}
                                onClick={() => handleHistorySort('amount')}
                              >
                                Amount
                              </TableSortLabel>
                            </TableCell>
                            <TableCell>Status</TableCell>
                            <TableCell>Action</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {(() => {
                            const sorted = getSortedHistory(paymentHistory);
                            const start = historyPage * historyRowsPerPage;
                            const slice = sorted.slice(start, start + historyRowsPerPage);
                            return slice.map(bill => (
                            <TableRow 
                              key={bill.billid} 
                              hover 
                              onClick={() => handleViewBillDetails(bill.billid, customer.customerid)} 
                              sx={{ 
                                cursor: 'pointer',
                                transition: 'background-color 0.2s',
                                '&:hover': { bgcolor: 'action.hover' }
                              }}
                            >
                              <TableCell>{formatMonth(bill.billedmonth)}</TableCell>
                              <TableCell align="right">{bill.previousreading}</TableCell>
                              <TableCell align="right">{bill.currentreading}</TableCell>
                              <TableCell align="right">{bill.consumption}</TableCell>
                              <TableCell>{formatDate(bill.datepaid)}</TableCell>
                              <TableCell align="right" fontWeight="bold">{formatCurrency(bill.totalbillamount)}</TableCell>
                              <TableCell>
                                <Chip 
                                  label={bill.paymentstatus} 
                                  size="small" 
                                  color={bill.paymentstatus === 'Paid' ? 'success' : bill.paymentstatus === 'Unpaid' ? 'error' : 'warning'} 
                                  variant="outlined"
                                />
                              </TableCell>
                              <TableCell>
                                <Tooltip title="Mark as Unpaid">
                                  <IconButton 
                                    size="small" 
                                    color="warning"
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      setBillToMarkUnpaid(bill);
                                      setShowUnpaidConfirm(true);
                                    }}
                                  >
                                    <UndoIcon fontSize="small" />
                                  </IconButton>
                                </Tooltip>
                              </TableCell>
                            </TableRow>
                            ));
                          })()}
                        </TableBody>
                      </Table>
                      <TablePagination
                        component="div"
                        rowsPerPageOptions={[10, 25, 50, 100]}
                        count={paymentHistory.length}
                        rowsPerPage={historyRowsPerPage}
                        page={historyPage}
                        onPageChange={(e, p) => setHistoryPage(p)}
                        onRowsPerPageChange={(e) => { setHistoryRowsPerPage(parseInt(e.target.value, 10)); setHistoryPage(0); }}
                      />
                    </TableContainer>
                  )}
                </CardContent>
              </Card>
            </Stack>
          );
        })()}

        {/* Dialogs */}
        <PaymentConfirmDialog
          isOpen={showPaymentConfirm && pendingPayment !== null}
          onClose={() => { setShowPaymentConfirm(false); setPendingPayment(null); }}
          onConfirm={handleProcessPayment}
          billCount={pendingPayment?.count || 0}
          grandTotal={pendingPayment?.totalAmount || 0}
          totalSurcharge={pendingPayment?.totalSurcharge || 0}
          creditBalance={pendingPayment?.creditBalance || 0}
          loading={loading}
          autoSelectedAmount={pendingPayment?.autoSelectedAmount} // Pass to dialog
        />

        <ConfirmationDialog
          isOpen={showUnpaidConfirm && billToMarkUnpaid !== null}
          onClose={() => { setShowUnpaidConfirm(false); setBillToMarkUnpaid(null); }}
          onConfirm={handleMarkAsUnpaid}
          title="Mark Bill as Unpaid?"
          message={billToMarkUnpaid ? `Are you sure you want to mark Bill #${billToMarkUnpaid.billid} as unpaid?` : ''}
          subMessage="This will reverse the payment status."
          confirmText="Mark as Unpaid"
          cancelText="Cancel"
          type="warning"
          loading={loading}
        />

        <BillDetailsModal 
          isOpen={showBillDetails}
          onClose={() => setShowBillDetails(false)}
          bill={selectedBillDetails?.bill}
          customer={selectedBillDetails?.customer}
          history={selectedBillDetails?.history}
        />

        <Dialog open={showAutoSelectDialog} onClose={() => setShowAutoSelectDialog(false)}>
          <DialogTitle>Auto-Select Bills</DialogTitle>
          <DialogContent>
            <DialogContentText sx={{ mb: 2 }}>
              Enter the amount you wish to pay. The system will automatically select the oldest unpaid bills that can be fully covered by this amount.
            </DialogContentText>
            <TextField
              autoFocus
              margin="dense"
              label="Amount to Pay"
              type="number"
              fullWidth
              variant="outlined"
              value={autoSelectAmount}
              onChange={(e) => setAutoSelectAmount(e.target.value)}
              InputProps={{
                startAdornment: <InputAdornment position="start">₱</InputAdornment>,
              }}
            />
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setShowAutoSelectDialog(false)}>Cancel</Button>
            <Button onClick={handleAutoSelectByAmount} variant="contained">Select Bills</Button>
          </DialogActions>
        </Dialog>

        <BillModal
          isOpen={showBillModal}
          onClose={() => {
            setShowBillModal(false);
            setPreSelectedCustomerForModal(null);
          }}
          mode={billModalMode}
          bill={selectedBillForModal}
          preSelectedCustomer={preSelectedCustomerForModal}
          onSuccess={handleModalSuccess}
          customerTypes={billCustomerTypes}
          surchargeSettings={surchargeSettings}
        />
        
        <ConfirmationDialog
          isOpen={showDeleteConfirm && billToDelete !== null}
          onClose={handleDeleteCancel}
          onConfirm={handleDeleteConfirm}
          title="Confirm Delete"
          message={billToDelete ? `Are you sure you want to delete bill #${billToDelete.billid}?` : ''}
          subMessage={billToDelete ? `Customer: ${billToDelete.customers?.name || 'N/A'} | Month: ${new Date(billToDelete.billedmonth).toLocaleDateString('en-PH', { year: 'numeric', month: 'long' })}` : ''}
          confirmText="Delete Bill"
          cancelText="Cancel"
          type="danger"
          loading={loading}
        />

      </Container>
    </Box>
  );
};

export default PaymentsPage;
