  async unpayApplication(applicationId) {
    try {
      const { error: delError } = await supabase
        .from('bplo_payments')
        .delete()
        .eq('application_id', applicationId)
      if (delError) throw delError
      const updateRes = await this.updateApplication(applicationId, { status: 'Unpaid' })
      if (!updateRes.success) throw new Error(updateRes.error || 'Failed to update application status')
      return { success: true }
    } catch (error) {
      return { success: false, error: error.message }
    }
  }
