  async checkNatureUsage(id, name) {
    try {
      // Check default charges (by ID)
      const { count: chargesCount, error: chargesError } = await supabase
        .from('bplo_default_charges')
        .select('*', { count: 'exact', head: true })
        .eq('nature_of_business_id', id);
      
      if (chargesError) throw chargesError;
      if (chargesCount > 0) return { inUse: true, reason: `Used in ${chargesCount} default charge(s)` };

      // Check applications (by Name)
      const { count: appsCount, error: appsError } = await supabase
        .from('bplo_applications')
        .select('*', { count: 'exact', head: true })
        .eq('nature_of_business', name);
        
      if (appsError) throw appsError;
      if (appsCount > 0) return { inUse: true, reason: `Used in ${appsCount} application(s)` };

      return { inUse: false };
    } catch (error) {
      return { inUse: false, error: error.message }; // Fail open or closed? Let's assume not in use if error, but log it.
    }
  },

