  // Fishing Gears
  async getFishingGears() {
    try {
      // We join with categories to get the category name if needed, 
      // but for now the frontend expects a flat list or we can shape it.
      // The frontend currently expects { id, name, category }
      // So we will select category name via join.
      const { data, error } = await supabase
        .from('bplo_fishing_gears')
        .select(`
          id, 
          name, 
          category_id,
          category:bplo_fishing_gear_categories(name)
        `)
        .order('name', { ascending: true })
      
      if (error) throw error
      
      // Transform data to match frontend expectation: { id, name, category: 'Category Name' }
      const formatted = (data || []).map(g => ({
        id: g.id,
        name: g.name,
        category_id: g.category_id,
        category: g.category?.name || 'Uncategorized'
      }))
      
      return { success: true, data: formatted }
    } catch (error) {
      return { success: false, error: error.message, data: [] }
    }
  },
